-- The notification stream sequence, and the IAM resources, actions and entitlements of the
-- Notification module.
--
-- The sequence is here rather than in 1008001_notification_schema.sql because that file is
-- generated by atlas from the model schemas, and the schema DSL has no way to express a sequence.
-- Regenerating the schema would discard anything added to it by hand.
--
-- WHY A SEQUENCE AT ALL: notification_recipients.stream_seq is the durable order of one person's
-- notification stream, and the cursor a disconnected client replays from. It must be monotonic
-- without taking a lock, which max()+1 cannot do under concurrency and a timestamp cannot do at
-- all. Gaps are explicitly allowed -- a rolled-back transaction consumes a number and no client
-- may wait for a missing one -- which is exactly what a sequence provides.

CREATE SEQUENCE IF NOT EXISTS "notification_stream_seq" AS bigint START WITH 1 INCREMENT BY 1;

-- IAM resources and actions for Notification: the notification itself, the per-person recipient
-- row that carries read state, and the per-channel delivery record. Every notification permission
-- row lives in this one file so a reviewer can see the module's entire permission surface at once.
--
-- The dynamic resource engine asserts permissions using the schema name as the resource code, so
-- these codes must stay byte-identical to the "notification_notification" /
-- "notification_recipient" / "notification_delivery" schema names. A code that drifts from its
-- schema denies every request, with nothing in the response pointing at the seed as the cause.
--
-- Deliberate omissions, each of which would otherwise look like something forgotten:
--
--   * There is no "create", "update" or "delete" on any of the three. Every write goes through
--     SendNotification or MarkRead, which enforce rules a raw CRUD write would bypass: the
--     transaction that keeps a notification and its recipients together, the idempotency guard,
--     and the rule that read_at is never overwritten. Seeding those actions would advertise
--     powers no endpoint offers.
--   * There is no set_archived. None of the three is archivable (BR 6, BR 8): a notification has
--     no lifecycle beyond expiring, and expiry neither deletes it nor hides it from history.
--   * "send" is seeded as an action but granted to NO role here. Raising a notification is
--     something a module does on a user's behalf over the command bus or a direct call, and it
--     has no REST route (BR 29). The action exists so a deployment can grant it to a service
--     principal deliberately; a role that held it by default could write into any inbox.

DO $$
BEGIN
	IF EXISTS (
		SELECT FROM information_schema.tables
		WHERE table_schema = 'public' AND table_name = 'iam_resources'
	) THEN
		INSERT INTO "iam_resources" (
			"id", "name", "code", "description", "owner_type", "max_scope", "min_scope", "created_at", "etag"
		) VALUES
		('01M3NOTIF00000000000000001', 'Notification', 'notification_notification', 'A message raised by a module for one or more people', 'nikkierp', 'tenant', 'org', NOW(), (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01M3NOTIF00000000000000002', 'Notification Recipient', 'notification_recipient', 'One person''s copy of a notification, carrying their own read state', 'nikkierp', 'tenant', 'org', NOW(), (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01M3NOTIF00000000000000003', 'Notification Delivery', 'notification_delivery', 'One attempt to deliver a notification over one channel', 'nikkierp', 'tenant', 'org', NOW(), (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text)
		ON CONFLICT ("id") DO NOTHING;
	END IF;

	IF EXISTS (
		SELECT FROM information_schema.tables
		WHERE table_schema = 'public' AND table_name = 'iam_actions'
	) THEN
		INSERT INTO "iam_actions" ("id", "name", "code", "description", "resource_id", "etag") VALUES
		-- Notification. Read for support and administration; send for the modules that raise them.
		('01M3NOTIF00000000000000011', 'Read', 'read', 'Read a notification', '01M3NOTIF00000000000000001', (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01M3NOTIF00000000000000012', 'Send', 'send', 'Raise a notification for one or more people', '01M3NOTIF00000000000000001', (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),

		-- Recipient. read_inbox covers the inbox list, the unread count and the stream: they answer
		-- the same question and differ only in transport. mark_read is separate because it writes.
		('01M3NOTIF00000000000000021', 'Read', 'read', 'Read a notification recipient record', '01M3NOTIF00000000000000002', (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01M3NOTIF00000000000000022', 'Read Inbox', 'read_inbox', 'Read your own notifications, unread count and stream', '01M3NOTIF00000000000000002', (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01M3NOTIF00000000000000023', 'Mark Read', 'mark_read', 'Mark your own notifications as read', '01M3NOTIF00000000000000002', (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),

		-- Delivery. Read only: deliveries are written by the module's own dispatcher, never
		-- through the API, and a forged delivery record would misreport what a provider accepted.
		('01M3NOTIF00000000000000031', 'Read', 'read', 'Read a delivery record', '01M3NOTIF00000000000000003', (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text)
		ON CONFLICT ("id") DO NOTHING;
	END IF;

	IF EXISTS (
		SELECT FROM information_schema.tables
		WHERE table_schema = 'public' AND table_name = 'iam_entitlements'
	) THEN
		-- The system "User" role gets read_inbox and mark_read, and nothing else.
		--
		-- Unlike most modules' blanket grants, this one is not a convenience: a notification inbox
		-- is useless if a person cannot read their own, and there is no role a deployment could
		-- assign to make that work for everybody. It is safe precisely because the endpoints
		-- resolve whose inbox is being read from the request context, never from the request -- so
		-- holding this grant lets a person read their own notifications and no one else's
		-- (BR 18, BR 29).
		--
		-- Scope is "org" rather than "tenant": a notification belongs to one organization, and a
		-- tenant-wide grant would let a member of two organizations see both inboxes as one list.
		INSERT INTO "iam_entitlements" (
			"id", "name", "description", "expression", "action_id", "resource_id", "role_id", "scope", "org_id", "org_unit_id", "is_archived", "created_at", "etag"
		) VALUES
		('01M3NOTIF00000000000000041', 'User - Read Own Notifications', 'Read your own notification inbox, unread count and stream', 'read_inbox:notification_recipient:org', '01M3NOTIF00000000000000022', '01M3NOTIF00000000000000002', '01KZJ5XRJDXSXZY0DKNNE6S086', 'org', NULL, NULL, false, NOW(), (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text),
		('01M3NOTIF00000000000000042', 'User - Mark Own Notifications Read', 'Mark your own notifications as read', 'mark_read:notification_recipient:org', '01M3NOTIF00000000000000023', '01M3NOTIF00000000000000002', '01KZJ5XRJDXSXZY0DKNNE6S086', 'org', NULL, NULL, false, NOW(), (EXTRACT(EPOCH FROM clock_timestamp()) * 1e9)::bigint::text)
		ON CONFLICT ("id") DO NOTHING;
	END IF;
END $$;
